entries[11426] = { ["name"] = "Eisbarriere", ["text"] = "305 Mana\nSofort 30 sek. Abklingzeit\nSchirmt Euch sofort ab und absorbiert 455 Schaden. Hält 1 Min. lang an. Solange der Schild hält, werden Zauber nicht unterbrochen." }
