entries[11441] = { ["name"] = "Welkberührung", ["text"] = "Fügt eine Chance hinzu, 'Welkberührung' auf den Gegner zu wirken, wenn der Zaubernde von einem Nahkampfangriff getroffen wird.\n(Procchance: 5%)" }
entries[11442] = { ["name"] = "Welkberührung", ["text"] = "Nahkampfreichweite\nSofort\nLässt einen Feind erkranken, verursacht alle 10 Sek. 2 Schattenschaden, entzieht alle 10 Sek. 2 Mana und überträgt sie auf den Zaubernden. Hält 3 Min. lang an." }
entries[11443] = { ["name"] = "Verkrüppeln", ["text"] = "8% von Grundmana 30 Meter Reichweite\nWirken in 3 sek.\nErhöht die Zeit zwischen Angriffen eines Feindes um 100%, verringert sein Bewegungstempo um 50% und zusätzlich seine Stärke um 50%. Hält 15 Sek. lang an." }
entries[11444] = { ["name"] = "Untote fesseln", ["text"] = "50 Mana 30 Meter Reichweite\nWirken in 2 sek.\nFesselt einen untoten Feind bis zu 20 Sek. lang und hindert ihn daran, Zauber zu wirken, anzugreifen oder sich zu bewegen. Jeglicher zugefügte Schaden wird das Ziel befreien. Es kann immer nur jeweils ein Ziel gefesselt sein." }
