entries[11451] = { ["name"] = "Öl des Feuerbrandes", ["text"] = "Wirken in 3 sek.\nReagenzien:\nFeuerblüte , Golddorn , Kristallphiole\n31\nBenutzen: Fügt allen Feinden in einem Umkreis von 5 Metern um den Zaubernden 15 Sek. lang alle 3 Sekunden 50 Feuerschaden zu. (3 Sek. Abklingzeit)" }
