entries[11459] = { ["name"] = "Stein der Weisen", ["text"] = "Wirken in 30 sek.\nReagenzien:\nEisenbarren (4), Schwarzes Vitriol , Lila Lotus (4), Feuerblüte (4)\nStein der Weisen\nWird beim Aufheben gebunden\nEinzigartig anlegbarSchmuck\n+5 Stärke\n+5 Beweglichkeit\n+5 Ausdauer\n+5 Intelligenz\n+5 Willenskraft\n35\nBenötigt Alchimie\n(200)\n\"Erforderlich für alchimistische Transmutation.\"" }
