entries[11574] = { ["name"] = "Verwunden", ["text"] = "10 Wut Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nBenötigt Kampfhaltung, Verteidigungshaltung\nVerwundet das Ziel, lässt es 21 Sek. lang bluten und fügt damit 147 Schaden plus [0.00743 * 7 * ((Haupthandwaffen-Max-Grundschaden + Haupthandwaffen-Min-Grundschaden) / 2 + Angriffskraft / 14 * Haupthandwaffen-Max-Grundgeschwindigkeit)] zusätzlichen Schaden (basierend auf Waffenschaden) zu." }
entries[11578] = { ["name"] = "Sturmangriff", ["text"] = "8 - 25 Meter Reichweite\nSofort 15 sek. Abklingzeit\nBenötigt Kampfhaltung\nStürmt auf einen Gegner zu, generiert 15 Wut und betäubt ihn 1 Sek. lang. Kann nicht im Kampf verwendet werden." }
entries[11580] = { ["name"] = "Donnerknall", ["text"] = "20 Wut\nSpontanzauber 4 sek. Abklingzeit\nBenötigt Kampfhaltung, Verteidigungshaltung\nDröhnt in der Nähe befindliche Feinde mit Donner zu, erhöht die Zeit zwischen ihren Angriffen 26 Sek. lang um 10% und fügt ihnen 82 Schaden zu. Diese Fähigkeit verursacht zusätzliche Bedrohung und wirkt auf maximal 4 Ziele." }
entries[11581] = { ["name"] = "Donnerknall", ["text"] = "20 Wut\nSpontanzauber 4 sek. Abklingzeit\nBenötigt Kampfhaltung, Verteidigungshaltung\nDröhnt in der Nähe befindliche Feinde mit Donner zu, erhöht die Zeit zwischen ihren Angriffen 30 Sek. lang um 10% und fügt ihnen 103 Schaden zu. Diese Fähigkeit verursacht zusätzliche Bedrohung und wirkt auf maximal 4 Ziele." }
entries[11584] = { ["name"] = "Überwältigen", ["text"] = "5 Wut Nahkampfreichweite\nSpontanzauber 5 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nBenötigt Kampfhaltung\nSofortige Überwältigung des Feindes, wodurch Waffenschaden plus 25 entsteht. Kann nur nach Ausweichen durch das Ziel verwendet werden. Auf 'Überwältigen' kann nicht mit Blocken, Ausweichen oder Parieren reagiert werden." }
entries[11585] = { ["name"] = "Überwältigen", ["text"] = "5 Wut Nahkampfreichweite\nSpontanzauber 5 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nBenötigt Kampfhaltung\nSofortiges Überwältigen des Feindes, wodurch Waffenschaden plus 35 entsteht. Kann nur nach Ausweichen durch das Ziel verwendet werden. Auf 'Überwältigen' kann nicht mit Blocken, Ausweichen oder Parieren reagiert werden." }
