entries[11596] = { ["name"] = "Rüstung zerreißen", ["text"] = "15 Wut Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nZerreißt die Rüstung des Ziels, verringert sie um 360 pro Einsatz von 'Rüstung zerreißen' und verursacht ein hohes Maß an Bedrohung. Kann bis zu 5-mal angewendet werden. Hält 30 Sek. lang an." }
