entries[11643] = { ["name"] = "Goldene Schuppenstulpen", ["text"] = "Wirken in 25 sek.\nTools: Schmiedehammer\nReagenzien:\nStahlbarren (10), Goldbarren (4), Schwerer Schleifstein (4)\nGoldene Schuppenstulpen\nWird beim Anlegen gebunden\nHände Kette\n146 Rüstung\n+11 Stärke\n+4 Willenskraft\nHaltbarkeit 35 / 35\n36" }
entries[11647] = { ["name"] = "Machtwort: Schild", ["text"] = "100 Mana 40 Meter Reichweite\nSofort 4 sek. Abklingzeit\nUmgibt den Zaubernden mit einem Schild, der bis zu 30 Sek. lang bestehen bleibt und maximal 801 körperlichen oder magischen Schaden absorbiert. Solange der Schild hält, werden Zauber nicht durch körperliche Angriffe unterbrochen." }
