entries[11675] = { ["name"] = "Seelendieb", ["text"] = "290 Mana 30 Meter Reichweite\nKanalisiert (Wirken in 15 sek.)\nEntzieht dem Ziel die Seele und verursacht 15 Sek. lang insgesamt 455 Schattenschaden. Wenn das Ziel beim Entziehen der Seele stirbt und Erfahrung oder Ehrenpunkte abgibt, erhält der Zaubernde einen Seelensplitter. Seelensplitter werden für andere Zauber benötigt." }
