entries[11707] = { ["name"] = "Fluch der Schwäche", ["text"] = "130 Mana 30 Meter Reichweite\nSofort\nDie Nahkampfangriffskraft des Ziels wird 2 Min. lang um 123 reduziert. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[11708] = { ["name"] = "Fluch der Schwäche", ["text"] = "175 Mana 30 Meter Reichweite\nSofort\nDie Nahkampfangriffskraft des Ziels wird 2 Min. lang um 163 reduziert. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[11711] = { ["name"] = "Fluch der Pein", ["text"] = "130 Mana 30 Meter Reichweite\nSofort\nVerflucht das Ziel mit Pein und fügt 24 Sek. lang insgesamt 504 Schattenschaden zu. Zuerst wird der Schaden langsam zugefügt und nimmt dann zu, bis der Fluch seine Gesamtdauer erreicht hat. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[11712] = { ["name"] = "Fluch der Pein", ["text"] = "170 Mana 30 Meter Reichweite\nSofort\nVerflucht das Ziel mit Pein und fügt 24 Sek. lang insgesamt 780 Schattenschaden zu. Zuerst wird der Schaden langsam zugefügt und nimmt dann zu, bis der Fluch seine Gesamtdauer erreicht hat. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[11713] = { ["name"] = "Fluch der Pein", ["text"] = "215 Mana 30 Meter Reichweite\nSofort\nVerflucht das Ziel mit Pein und fügt 24 Sek. lang insgesamt 1044 Schattenschaden zu. Zuerst wird der Schaden langsam zugefügt und nimmt dann zu, bis der Fluch seine Gesamtdauer erreicht hat. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[11717] = { ["name"] = "Fluch der Tollkühnheit", ["text"] = "115 Mana 30 Meter Reichweite\nSofort\nVerflucht das Ziel mit Tollkühnheit, wodurch sich die Nahkampfangriffskraft 2 Min. lang um 90 erhöht, jedoch die Rüstung um 640 verringert. Mit einem Fluch belegte Feinde fliehen nicht und ignorieren Furcht- und Entsetzenseffekte. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[11719] = { ["name"] = "Fluch der Sprachen", ["text"] = "110 Mana 30 Meter Reichweite\nSofort\nZwingt das Ziel, Dämonisch zu sprechen, und verlangsamt die Zauberzeit um 60%. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem Ziel aktiv sein. Hält 30 Sek. lang an." }
entries[11721] = { ["name"] = "Fluch der Elemente", ["text"] = "150 Mana 30 Meter Reichweite\nSofort\nVerflucht das Ziel und verringert 5 Min. lang seinen Arkan-, Feuer-, Frost- und Schattenwiderstand um 60. Erhöht außerdem den erlittenen Arkan-, Feuer-, Frost- und Schattenschaden des Ziels um 8%. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[11722] = { ["name"] = "Fluch der Elemente", ["text"] = "200 Mana 30 Meter Reichweite\nSofort\nVerflucht das Ziel und verringert 5 Min. lang seinen Arkan-, Feuer-, Frost- und Schattenwiderstand um 75. Erhöht außerdem den erlittenen Arkan-, Feuer-, Frost- und Schattenschaden des Ziels um 10%. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
