entries[11729] = { ["name"] = "Gesundheitsstein herstellen", ["text"] = "750 Mana\nWirken in 3 sek.\nReagenzien:\nSeelensplitter\nLässt einen großen Gesundheitsstein entstehen, der verwendet werden kann, um sofort 800 Gesundheit wiederherzustellen.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
entries[11730] = { ["name"] = "Gesundheitsstein herstellen", ["text"] = "1120 Mana\nWirken in 3 sek.\nReagenzien:\nSeelensplitter\nLässt einen erheblichen Gesundheitsstein entstehen, der verwendet werden kann, um sofort 1200 Gesundheit wiederherzustellen.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
entries[11732] = { ["name"] = "Erheblicher Gesundheitsstein", ["text"] = "Sofort\nStellt sofort 1200 Gesundheit wieder her." }
entries[11733] = { ["name"] = "Dämonenrüstung", ["text"] = "320 Mana\nSofort\nSchützt den Zaubernden und erhöht die Rüstung um 390, den Schattenwiderstand um 9 und stellt alle 5 Sek. 11 Gesundheit wieder her. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Hexenmeister aktiv sein. Hält 30 Min. an." }
entries[11734] = { ["name"] = "Dämonenrüstung", ["text"] = "460 Mana\nSofort\nSchützt den Zaubernden und erhöht die Rüstung um 480, den Schattenwiderstand um 12 und stellt alle 5 Sek. 13 Gesundheit wieder her. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Hexenmeister aktiv sein. Hält 30 Min. an." }
