entries[12715] = { ["name"] = "Rezept für Goblinraketentreibstoff", ["text"] = "Wirken in 25 sek.\nReagenzien:\nLeeres Pergament , Ingenieurstinte\nRezept: Goblinraketentreibstoff\nBenötigt Alchimie\n(210)\nBenutzen: Lehrt Euch die Herstellung von Goblinraketentreibstoff." }
entries[12716] = { ["name"] = "Goblinmörser", ["text"] = "Wirken in 25 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilrohr (2), Mithrilbarren (4), Robustes Sprengpulver (5), Goldkraftkern , Elementarfeuer\nWird beim Anlegen gebunden\nSchmuck\nBenötigt Ingenieurskunst\n(205)\nBenutzen: Fügt 383 bis 517 Feuerschaden zu und betäubt 3 Sek. lang die Ziele in einem Umkreis von 5 Metern. (10 Min Abklingzeit)\n6 Aufladungen" }
